# A steward merges a person into another (not themselves; neither retired): the merged person's claims,
# name and aliases, patrons and pool memberships pass to the other, and they leave the sheet.
guard:
  class: net.officefloor.hq.app.settings.RefuseViewer
  next: merge
merge:
  class: net.officefloor.hq.app.person.MergePerson
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.settings.SettingsRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** A steward merges a person into another: the merged person's claims move to the other (numbers and dates
 *  kept, listed after the other's in the order they were added, each keeping any figure a statement bound), their
 *  name and aliases become the other's aliases, their patrons, the people naming them and their pool memberships
 *  pass to the other, and they leave the sheet (their statements joined to the other's — the other's count becomes their own plus
 *  the merged person's, the other's last statement staying theirs, or becoming the merged person's when they had
 *  none; holds, watchers and contact dropped). Refused for anyone
 *  but a steward, for the same person, and when either of them is retired. */
public class MergePerson {
    public void merge(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            @RequestBody MergeRequest request, ServerHttpConnection connection, PersonRepository people,
            ClaimRepository claims, SettingsRepository settings, Audit audit, Rollup rollup, Out<Person> person)
            throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        long pid;
        try {
            pid = Long.parseLong(personId == null ? "" : personId.trim());
        } catch (NumberFormatException e) {
            throw new BadRequestException("no such person");
        }
        Person from = people.find(id, pid);
        if (from == null) {
            throw new BadRequestException("no such person");
        }
        if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
            throw new BadRequestException("only a steward can merge people");
        }
        Person into = request == null || request.intoId() == null ? null : people.find(id, request.intoId());
        if (into == null) {
            throw new BadRequestException("choose the person to merge into");
        }
        if (into.id() == pid) {
            throw new BadRequestException("a person cannot be merged into themselves");
        }
        if (from.retired()) {
            throw new BadRequestException(from.name() + " is retired");
        }
        if (into.retired()) {
            throw new BadRequestException(into.name() + " is retired");
        }
        Rollup.Snapshot before = rollup.take(id);
        claims.moveAll(id, pid, into.id());
        people.merge(id, pid, into.id());
        audit.record("PERSON_MERGED sheet=" + id + " by=" + by + " from=" + from.name() + " into=" + into.name());
        rollup.record(id, by, before);
        person.set(people.find(id, into.id()));
    }
}
package net.officefloor.hq.app.person;

/** The merge form: the id of the person to merge this person into. */
public record MergeRequest(Long intoId) {
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PersonCells, PersonColumnHead } from '../../slots/defs/personRow';
import { usePeople, type Person } from '../people/usePeople';
import { usePersonRowAction } from '../people/usePersonRowAction';

/** A steward merges a person into another: a select of the other person and a merge button. The merged
 *  person's claims, name and aliases, patrons and pool memberships pass to the other and they leave the list,
 *  so every figure on the sheet is re-read. Anyone else, the same person, or either of them retired is
 *  refused with the row's error. */
function PersonMerge({ sheetId, personId }: { sheetId: string; personId: number }) {
  const people = usePeople(sheetId);
  const queryClient = useQueryClient();
  const [chosen, setChosen] = useState('');

  const merge = useMutation({
    mutationFn: (intoId: number) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/merge`, { intoId }),
    onSuccess: async () => {
      setChosen('');
      await queryClient.invalidateQueries({ queryKey: ['sheet', sheetId] });
    },
  });
  const announce = usePersonRowAction(sheetId, personId, merge.reset);

  return (
    <td>
      <select
        data-testid="person-merge-into"
        value={chosen}
        onChange={(e) => {
          setChosen(e.target.value);
          merge.reset();
        }}
      >
        <option value="">Merge into…</option>
        {(people.data ?? []).map((p) => (
          <option key={p.id} value={String(p.id)}>
            {p.name}
          </option>
        ))}
      </select>{' '}
      <button
        type="button"
        data-testid="person-merge"
        disabled={merge.isPending}
        onClick={() => {
          announce();
          merge.reset();
          merge.mutate(Number(chosen));
        }}
      >
        Merge
      </button>
      {merge.isError && <span data-testid="person-error">{merge.error.message}</span>}
    </td>
  );
}

export const contributions = [
  PersonColumnHead.fill({ order: 55, Component: () => <th>Merge</th> }),
  PersonCells.fill({ order: 55, Component: PersonMerge }),
];

